// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {CVXStaker, ICVXBooster, IERC20} from "../src/CVXStaker.sol";

contract InvMutTest is Test {
    CVXStaker c;

    function setUp() public {
        c = new CVXStaker(address(new __InvMutHandleStub()), IERC20(address(this)), ICVXBooster(address(this)), new address[](0));
    }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(actor != address(this));

        vm.prank(actor);
        try c.transferOwnership(newOwner) {
            // Reference: only the owner (this contract) may transfer ownership.
            assertTrue(c.owner() == address(this));
        } catch {
            assertTrue(true);
        }
    }
}

